     gen_counter_incr_without_pc(asm, counter);

+    if get_option!(gen_stats) && counter != Counter::yjit_insns_count {
+        let ptr = census_ptr(&counter.get_name(), pc);
+        let reg = asm.load(Opnd::const_ptr(ptr as *const u8));
