@@ -9,6 +9,7 @@ use std::collections::HashMap;
 use crate::codegen::CodegenGlobals;
 use crate::cruby::*;
 use crate::options::*;
+use crate::utils::iseq_get_location;
 use crate::yjit::{yjit_enabled_p, rb_yjit_compiling_p, out_of_memory_p, YJIT_INIT_TIME};

 #[cfg(feature = "stats_allocator")]
@@ -46,6 +47,35 @@ static mut ISEQ_NAME_TO_IDX: Option<HashMap<String, usize>> = None;
 static mut CFUNC_CALL_COUNT: Option<Vec<u64>> = None;
 static mut ISEQ_CALL_COUNT: Option<Vec<u64>> = None;

+// Y2 diagnostic-only counters. Boxes keep emitted addresses stable. Store
+// location strings, not Ruby objects, so the census does not retain receivers.
+static mut CENSUS_PCS: Option<HashMap<usize, String>> = None;
+static mut CENSUS_COUNTS: Option<HashMap<String, Box<u64>>> = None;
+static mut CENSUS_ATTEMPTS: u64 = 0;
+
+pub fn census_attempts_ptr() -> *mut u64 {
+    addr_of_mut!(CENSUS_ATTEMPTS)
+}
+
+pub fn census_register(iseq: IseqPtr, idx: u16, pc: *const VALUE) {
+    if get_option!(gen_stats) {
+        unsafe {
+            CENSUS_PCS.get_or_insert_with(HashMap::new).insert(
+                pc as usize, format!("{}|{idx}", iseq_get_location(iseq, idx)));
+        }
+    }
+}
+
+pub fn census_ptr(reason: &str, pc: *const VALUE) -> *mut u64 {
+    unsafe {
+        let location = CENSUS_PCS.as_ref().and_then(|pcs| pcs.get(&(pc as usize)))
+            .cloned().unwrap_or_else(|| "unregistered".to_string());
+        let key = format!("Y2|{reason}|{location}");
+        &mut **CENSUS_COUNTS.get_or_insert_with(HashMap::new)
+            .entry(key).or_insert_with(|| Box::new(0))
+    }
+}
+
 /// Assign an index to a given cfunc name string
 pub fn get_cfunc_idx(name: &str) -> usize {
     // SAFETY: We acquire a VM lock and don't create multiple &mut references to these static mut variables.
@@ -828,6 +858,13 @@ fn rb_yjit_gen_stats_dict(key: VALUE) -> VALUE {
             set_stat_usize!(hash, counter_name, counter_val as usize);
         }

+        if let Some(counts) = CENSUS_COUNTS.as_ref() {
+            for (name, count) in counts {
+                set_stat_usize!(hash, name, **count as usize);
+            }
+        }
+        set_stat_usize!(hash, "y2_send_dynamic_attempts", CENSUS_ATTEMPTS as usize);
+
         let mut side_exits = 0;

         // For each entry in exit_op_count, add a stats entry with key "exit_INSTRUCTION_NAME"
@@ -1087,6 +1124,7 @@ pub extern "C" fn rb_yjit_count_side_exit_op(exit_pc: *const VALUE) -> *const VA

         // Increment the exit op count for this opcode
         EXIT_OP_COUNT[opcode as usize] += 1;
+        *census_ptr(&format!("exit_{}", insn_name(opcode as usize)), exit_pc) += 1;
     };

     // This function must return exit_pc!

